function notImplemented<TArgs extends any[]>(functionName: string) {
  return async (...args: TArgs): Promise<never> => {
    action(functionName)(...args);
    throw new Error("Method not implemented");
  };
}

export function mockCheckoutService(
  giftCards: Array<GiftCardPaymentResponseItem>,
  withGiftCardInCart: boolean,
  setArgs: (args: { giftCards: Array<GiftCardPaymentResponseItem> }) => void,
) {
  Object.assign(CheckoutService, {
    getCart: () => Promise.resolve(cartResponse(withGiftCardInCart)),
    createKlarnaPaymentForCart: async (...params) => {
      action("createKlarnaPaymentForCart")(...params);
      await new Promise((resolve) => setTimeout(resolve, 200)); // Simulate network delay
      return paymentResponse(giftCards);
    },
    patchPaymentForCart: async (...params) => {
      action("patchPaymentForCart")(...params);
      await new Promise((resolve) => setTimeout(resolve, 200)); // Simulate network delay
      return paymentResponse(giftCards);
    },
    getPaymentStatus: async (...params) => {
      action("getPaymentStatus")(...params);
      await new Promise((resolve) => setTimeout(resolve, 200)); // Simulate network delay
      return paymentResponse(giftCards);
    },
    addGiftCardToCart: async (cartId, giftCard) => {
      action("addGiftCardToCart")(cartId, giftCard);
      const newCards = [
        ...giftCards,
        {
          cardIdentifier: giftCard.cardIdentifier,
          expiresOn: "2024-12-31T23:59:59Z",
          balanceBeforePayment: 50,
          reservedAmount: 50,
          balanceAfterPayment: 0,
        },
      ];
      setArgs({
        giftCards: newCards,
      });
      await new Promise((resolve) => setTimeout(resolve, 200)); // Simulate network delay
      return paymentResponse(newCards);
    },
    removeGiftCardFromCart: async (cartId, giftCardIdentifier) => {
      action("removeGiftCardFromCart")(cartId, giftCardIdentifier);
      const newCards = giftCards.filter((card) => card.cardIdentifier !== giftCardIdentifier);
      await new Promise((resolve) => setTimeout(resolve, 200)); // Simulate network delay
      setArgs({
        giftCards: newCards,
      });
      return paymentResponse(newCards);
    },
    addItemToCart: notImplemented("addItemToCart"),
    removeItemFromCart: notImplemented("removeItemFromCart"),
    addSubitemToCartItem: notImplemented("addSubitemToCartItem"),
    removeSubitemFromCartItem: notImplemented("removeSubitemFromCartItem"),
    createCart: notImplemented("createCart"),
    finalizeKlarnaOrder: notImplemented("finalizeKlarnaOrder"),
    patchItemInCart: notImplemented("patchItemInCart"),
    finalizeZeroAmountPayment: notImplemented("finalizeZeroAmountPayment"),
    patchCart: notImplemented("patchCart"),
    createNetsPaymentForCart: notImplemented("createNetsPaymentForCart"),
    validateNetsPayment: notImplemented("validateNetsPayment"),
    addVoucherToCart: notImplemented("addVoucherToCart"),
    removeVoucherFromCart: notImplemented("removeVoucherFromCart"),
  } satisfies ICheckoutService);
}

